const items = $input.all();
const results = [];
for (const item of items) {
  const row = item.json;
  const rate = Number(row.cashback_percent || row.rate || 0);
  if (rate < 8) continue;
  let score = Math.min(100, Math.floor(rate * 4.5));
  let priority = 'NORMAL';
  if (rate >= 20) priority = 'CRITICAL_BUG';
  else if (rate >= 12) priority = 'HIGH';
  results.push({
    json: {
      category: 'cashback_max',
      title: `${rate}% de Cashback na ${row.store || 'Loja'} (${row.provider || 'Méliuz/Inter'})`,
      description: `Taxa turbinada de retorno. Economia direta na compra com link parametrizado.`,
      opportunity_price: rate,
      original_price: 100.00,
      discount_percentage: rate,
      source_name: row.provider || 'Cashback Radar',
      source_url: row.url || 'https://exemplo.com',
      affiliate_url: row.affiliate_redirect_url || row.url,
      evaluation_score: score,
      priority
    }
  });
}
return results;
